def countFollowCircles(follows):
    n = len(follows)
    parent = list(range(n))

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    circles = n
    for i in range(n):
        row = follows[i]
        for j in range(n):
            if i != j and row[j]:
                a, b = find(i), find(j)
                if a != b:
                    parent[a] = b
                    circles -= 1
    return circles
